// Discount.java
public interface Discount {
    long apply(long totalPence);
}

// PercentOff.java
public class PercentOff implements Discount {
    private final int percent;

    public PercentOff(int percent) {
        this.percent = percent;
    }

    @Override
    public long apply(long totalPence) {
        return totalPence - (totalPence * percent / 100);
    }
}

// FixedOff.java
public class FixedOff implements Discount {
    private final long pence;

    public FixedOff(long pence) {
        this.pence = pence;
    }

    @Override
    public long apply(long totalPence) {
        return Math.max(0, totalPence - pence);
    }
}

// Basket.java
import java.util.ArrayList;
import java.util.List;

public class Basket {
    private final long totalPence;
    private final List<Discount> discounts = new ArrayList<>();

    public Basket(long totalPence) {
        this.totalPence = totalPence;
    }

    public void add(Discount d) {
        discounts.add(d);
    }

    public long total() {
        long t = totalPence;
        for (Discount d : discounts) {
            t = d.apply(t);
        }
        return t;
    }
}

