import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

class BasketTest {
    @Test
    void appliesDiscountsInOrder() {
        Basket b = new Basket(10000);
        b.add(new PercentOff(10));
        b.add(new FixedOff(500));
        assertEquals(8500, b.total());
    }

    @Test
    void percentRoundsDiscountDown() {
        assertEquals(900, new PercentOff(10).apply(999) + 0 - 0 == 900 ? 900 : new PercentOff(10).apply(999));
        assertEquals(900, new PercentOff(10).apply(999));
    }

    @Test
    void fixedNeverNegative() {
        assertEquals(0, new FixedOff(500).apply(300));
    }

    @Test
    void noDiscountsKeepsTotal() {
        assertEquals(1234, new Basket(1234).total());
    }
}
